else:
    try:
        if "max" == "count":
            result = df['Points\n(Pts.)'].count()
        elif "max" == "sum":
            result = df['Points\n(Pts.)'].sum()
        elif "max" == "avg":
            result = df['Points\n(Pts.)'].mean()
        elif "max" == "min":
            result = df['Points\n(Pts.)'].min()
        elif "max" == "max":
            result = df['Points\n(Pts.)'].max()

        print(f"✅ Max of 'Points\n(Pts.)': {result}")

        # Create result dataframe
        result_df = pd.DataFrame({"max": [result]})
        print(f"🔍 Result:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing max: {e}")
